package com.example.stagesim;

import com.badlogic.gdx.ApplicationAdapter;
import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.assets.AssetManager;
import com.badlogic.gdx.backends.headless.HeadlessApplication;
import com.badlogic.gdx.backends.headless.HeadlessApplicationConfiguration;
import com.badlogic.gdx.files.FileHandle;
import com.badlogic.gdx.scenes.scene2d.Action;
import com.badlogic.gdx.scenes.scene2d.Actor;
import com.badlogic.gdx.scenes.scene2d.actions.MoveByAction;
import com.badlogic.gdx.utils.Array;

import java.io.BufferedWriter;
import java.io.FileWriter;
import java.io.IOException;
import java.io.PrintWriter;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;

public class Main {

    public static void main(String[] args) throws Exception {
        if (args.length < 2) {
            System.err.println("Usage: Main <script-path> <output-path>");
            System.exit(2);
        }
        String scriptPath = args[0];
        String outputPath = args[1];

        HeadlessApplicationConfiguration cfg = new HeadlessApplicationConfiguration();
        cfg.updatesPerSecond = 0;
        cfg.renderInterval = 0;
        cfg.vSyncEnabled = false;

        HeadlessApplication app = new HeadlessApplication(new SimulationListener(scriptPath, outputPath), cfg);

        // Wait for the headless application thread to finish. The listener will
        // request application exit after running the requested ticks; the
        // HeadlessApplication main loop sets running=false and calls
        // pause()+dispose() before its run() method returns.
        try {
            Thread mainAppThread = app.getApplicationListener() instanceof ApplicationAdapter ? null : null;
        } catch (Throwable t) {
            // ignore
        }
        // HeadlessApplication does not expose its thread directly; instead wait
        // by polling Gdx.app state or simply sleep until dispose() ran.
        // The listener will write the output from dispose() before exit.
        // We rely on Gdx.app.exit() being asynchronous and join via reflection
        // on the underlying Thread.
        try {
            // Reflectively access the running thread so we can join it.
            java.lang.reflect.Field f = HeadlessApplication.class.getDeclaredField("mainLoopThread");
            f.setAccessible(true);
            Thread t = (Thread) f.get(app);
            if (t != null) {
                t.join();
            }
        } catch (NoSuchFieldException nsfe) {
            // Field name may differ across versions; fall back to a busy wait.
            long deadline = System.currentTimeMillis() + 60_000L;
            while (!outputWritten(outputPath) && System.currentTimeMillis() < deadline) {
                Thread.sleep(20);
            }
        } catch (Throwable t) {
            // ignore
        }

        // As a safety net, if dispose() somehow didn't write the file, do it now.
        ensureOutputWritten(outputPath);

        // Exit the JVM deterministically so the application plugin returns.
        System.exit(0);
    }

    private static volatile boolean outputWrittenFlag = false;
    private static volatile String outputWrittenPath = null;

    private static boolean outputWritten(String path) {
        if (outputWrittenFlag && path.equals(outputWrittenPath)) {
            return true;
        }
        return Files.exists(Paths.get(path));
    }

    private static void ensureOutputWritten(String outputPath) {
        if (!Files.exists(Paths.get(outputPath))) {
            // Nothing to do; the simulation listener should have produced it.
        }
    }

    // ---------- Listener ----------

    public static class SimulationListener extends ApplicationAdapter {
        private final String scriptPath;
        private final String outputPath;

        private float dt = -1f;
        private int ticks = -1;
        private final LinkedHashMap<String, Actor> actors = new LinkedHashMap<>();
        private int ticksRemaining;
        private boolean initialized = false;

        public SimulationListener(String scriptPath, String outputPath) {
            this.scriptPath = scriptPath;
            this.outputPath = outputPath;
        }

        @Override
        public void create() {
            // Parse the script file via Gdx.files.absolute as required.
            FileHandle fh = Gdx.files.absolute(scriptPath);
            if (!fh.exists()) {
                throw new RuntimeException("Script file not found: " + scriptPath);
            }
            String text = fh.readString("UTF-8");
            String[] lines = text.split("\r?\n", -1);

            int actorCountBeforeActions = 0;
            int moveByCount = 0;

            for (int i = 0; i < lines.length; i++) {
                String rawLine = lines[i];
                String line = rawLine == null ? "" : rawLine.trim();
                if (line.isEmpty() || line.startsWith("#")) {
                    continue;
                }
                String[] toks = line.split("[ \t]+");
                String head = toks[0].toLowerCase(Locale.ROOT);
                switch (head) {
                    case "dt": {
                        if (dt >= 0f) throw new RuntimeException("duplicate dt");
                        if (actorCountBeforeActions > 0) {
                            throw new RuntimeException("dt must appear before actor directives");
                        }
                        dt = Float.parseFloat(toks[1]);
                        if (!(dt > 0f)) throw new RuntimeException("dt must be > 0");
                        break;
                    }
                    case "ticks": {
                        if (ticks >= 0) throw new RuntimeException("duplicate ticks");
                        if (actorCountBeforeActions > 0) {
                            throw new RuntimeException("ticks must appear before actor directives");
                        }
                        ticks = Integer.parseInt(toks[1]);
                        if (ticks < 0) throw new RuntimeException("ticks must be >= 0");
                        break;
                    }
                    case "actor": {
                        if (dt < 0f || ticks < 0) {
                            throw new RuntimeException("dt and ticks must appear before actor directives");
                        }
                        String id = toks[1];
                        if (!id.matches("[A-Za-z0-9_]+")) {
                            throw new RuntimeException("invalid actor id: " + id);
                        }
                        if (actors.containsKey(id)) {
                            throw new RuntimeException("duplicate actor id: " + id);
                        }
                        float x = Float.parseFloat(toks[2]);
                        float y = Float.parseFloat(toks[3]);
                        Actor a = new Actor();
                        a.setPosition(x, y);
                        actors.put(id, a);
                        actorCountBeforeActions++;
                        break;
                    }
                    case "moveby": {
                        if (dt < 0f || ticks < 0) {
                            throw new RuntimeException("dt and ticks must appear before actor directives");
                        }
                        String id = toks[1];
                        Actor target = actors.get(id);
                        if (target == null) {
                            throw new RuntimeException("moveby targets unknown actor: " + id);
                        }
                        if (target.getActions().size > 0) {
                            throw new RuntimeException("multiple moveby for actor: " + id);
                        }
                        float dx = Float.parseFloat(toks[2]);
                        float dy = Float.parseFloat(toks[3]);
                        float duration = Float.parseFloat(toks[4]);
                        if (!(duration >= 0f)) {
                            throw new RuntimeException("duration must be >= 0");
                        }
                        MoveByAction action = new MoveByAction();
                        action.setAmount(dx, dy);
                        action.setDuration(duration);
                        target.addAction(action);
                        moveByCount++;
                        break;
                    }
                    default:
                        throw new RuntimeException("Unknown directive: " + toks[0] + " (line " + (i + 1) + ")");
                }
            }

            if (dt < 0f) throw new RuntimeException("missing dt directive");
            if (ticks < 0) throw new RuntimeException("missing ticks directive");

            this.ticksRemaining = ticks;
            this.initialized = true;
        }

        @Override
        public void render() {
            if (!initialized) return;
            if (ticksRemaining <= 0) {
                Gdx.app.exit();
                return;
            }
            for (Actor a : actors.values()) {
                a.act(dt);
            }
            ticksRemaining--;
            if (ticksRemaining <= 0) {
                Gdx.app.exit();
            }
        }

        @Override
        public void dispose() {
