            // before the JVM exits.
            try (BufferedWriter bw = new BufferedWriter(
                    new PrintWriter(new FileWriter(outputPath, false)))) {
                for (Map.Entry<String, Actor> e : actors.entrySet()) {
                    Actor a = e.getValue();
