                    float y = a.getY();
                    String line = e.getKey() + "=" + String.format(Locale.ROOT, "%.6f,%.6f", x, y);
                    bw.write(line);
                    bw.write("\n");
                }
                bw.flush();
            } catch (IOException ex) {
                throw new RuntimeException("failed to write output", ex);
            }
            outputWrittenFlag = true;
            outputWrittenPath = outputPath;
        }
    }
}
